def walk(node, depth=0, out=None):
    if out is None: out = []
    title = node.get('title') or ''
    if isinstance(title, dict):
        title = title.get('text') or str(title)
    if title:
        out.append(('  '*depth) + str(title)[:200])
    for c in node.get('children', {}).get('attached', []) if isinstance(node.get('children'), dict) else node.get('children', []) or []:
        if isinstance(c, dict):
            walk(c, depth+1, out)
    # xmind zen format: topics
    for c in node.get('topics', []) or []:
        walk(c, depth+1, out)
    return out

